#!/usr/bin/env python3
"""Build useful, indexable creator tools without a frontend dependency."""
from pathlib import Path
import html

ROOT = Path(__file__).resolve().parents[1]
PAGES = {
    'script-templates': ('Script Template Builder', 'Choose a speaking format, add your ideas, and build a script you can rehearse immediately.', '''<label>Format<select id="scene"><option value="youtube">YouTube introduction</option><option value="pitch">Product pitch</option><option value="course">Online lesson</option><option value="meeting">Team update</option><option value="podcast">Podcast opening</option><option value="speech">Short speech</option><option value="live">Livestream welcome</option><option value="interview">Self introduction</option></select></label><label>Script language<select id="language"><option value="en">English</option><option value="zh">简体中文</option></select></label><label>Topic / product / your name<input id="topic" maxlength="200" placeholder="A simpler way to plan your week"></label><label>Who is this for?<input id="audience" maxlength="200" placeholder="Busy creators"></label><label>Key points (one per line)<textarea id="points" rows="4" placeholder="The problem you solve&#10;Your practical advice&#10;A concrete example"></textarea></label><label>Closing action<input id="action" maxlength="300" placeholder="Try this today and share what changed"></label><button id="generate" class="primary">Build my script</button>'''),
    'script-extractor': ('Transcript Cleaner', 'Turn a pasted transcript or subtitle file into an editable speaking script. Files are processed on this device.', '''<label>Import text or subtitles<input id="transcript-file" type="file" accept=".txt,.md,.srt,.vtt"></label><p class="hint">TXT, Markdown, SRT and VTT · up to 5 MB. This tool cleans existing text; it does not transcribe audio, video or links.</p><label>Transcript<textarea id="transcript" rows="10" placeholder="Paste your transcript or subtitle contents here"></textarea></label><button id="clean" class="primary">Clean transcript</button>'''),
    'publishing-assistant': ('Publishing Checklist & Copy Builder', 'Prepare a title, description and tags from your script, then export an editable publishing package.', '''<label>Video title<input id="video-title" maxlength="200" placeholder="What viewers will learn"></label><label>Script<textarea id="publish-script" rows="8" placeholder="Paste your finished script"></textarea></label><label>Call to action<input id="publish-action" maxlength="300" placeholder="Subscribe for the next lesson"></label><label>Keywords (comma separated)<input id="keywords" maxlength="500" placeholder="content creation, speaking, tutorial"></label><button id="package" class="primary">Build publishing copy</button><p class="hint">Uses your own words; no AI request or upload. Review the copy before publishing. Timed subtitles require a transcript aligned to your recording.</p>''')
}

for slug, (title, description, form) in PAGES.items():
    links = ''.join(f'<a href="/{s}/" {"aria-current=page" if s == slug else ""}>{html.escape(v[0])}</a>' for s, v in PAGES.items())
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | CuePrompt</title><meta name="description" content="{description}"><link rel="canonical" href="https://cueprompt-studio.mauvejay6.chatgpt.site/{slug}/"><link rel="stylesheet" href="/creator-tools.css"><script src="/creator-tools.js" defer></script></head><body data-tool="{slug}"><header><a class="brand" href="/">CuePrompt</a><a href="/#studio">Open studio ↗</a></header><main><p class="eyebrow">FROM IDEA TO CAMERA</p><h1>{title}</h1><p class="intro">{description}</p><nav aria-label="Creator tools">{links}</nav><div class="workspace"><section class="card">{form}</section><section class="card"><h2>Your editable draft</h2><label>Title<input id="result-title" value="My next video"></label><label>Draft<textarea id="result" rows="16" placeholder="Your draft will appear here. You can edit it before using it."></textarea></label><p id="status" role="status" aria-live="polite"></p><div class="actions"><button id="use" class="primary">Use in teleprompter →</button><button id="download">Download TXT</button><button id="copy">Copy</button></div></section></div><footer>Private by design. Drafts stay in this browser. <a href="/">Back to CuePrompt</a></footer></main></body></html>'''
    folder = ROOT / 'dist' / slug
    folder.mkdir(parents=True, exist_ok=True)
    (folder / 'index.html').write_text(page, encoding='utf-8')
